// src/server/tools/diagnostics.ts
function formatDiagnosticsForLLM(diagnostics) {
  if (diagnostics.length === 0) return "";
  const errors = diagnostics.filter((d) => d.severity === "error");
  const warnings = diagnostics.filter((d) => d.severity === "warning");
  let output = "\n\nLSP found ";
  const parts = [];
  if (errors.length > 0) parts.push(`${errors.length} error(s)`);
  if (warnings.length > 0) parts.push(`${warnings.length} warning(s)`);
  output += parts.join(", ") + ":\n";
  const sorted = [...diagnostics].sort((a, b) => {
    const severityOrder = { error: 0, warning: 1, info: 2, hint: 3 };
    return severityOrder[a.severity] - severityOrder[b.severity];
  });
  for (const d of sorted.slice(0, 10)) {
    output += `- Line ${d.range.start.line + 1}: [${d.severity}] ${d.message}
`;
  }
  if (diagnostics.length > 10) {
    output += `... and ${diagnostics.length - 10} more
`;
  }
  return output;
}
function appendLspInstallHint(output, lspManager, path) {
  if (!lspManager) return output;
  const hint = lspManager.getInstallHint(path);
  if (!hint) return output;
  return output + `

\u26A0\uFE0F Language server not installed. To enable diagnostics: \`${hint}\``;
}

