// src/server/tools/sub-agent.ts
var callSubAgentTool = {
  name: "call_sub_agent",
  definition: {
    type: "function",
    function: {
      name: "call_sub_agent",
      description: "Call a sub-agent to perform a specialized task. Available sub-agents: verifier (verify criteria), code_reviewer (review code quality), explorer (explore codebase). The sub-agent will execute with isolated context and return a text result.",
      parameters: {
        type: "object",
        properties: {
          subAgentType: {
            type: "string",
            description: "Type of sub-agent to call"
          },
          prompt: {
            type: "string",
            description: "Task description for the sub-agent. Be specific about what you need."
          }
        },
        required: ["subAgentType", "prompt"]
      }
    }
  },
  async execute(args, context) {
    const startTime = Date.now();
    if (!args["subAgentType"]) {
      return {
        success: false,
        error: "Missing required parameter: subAgentType",
        durationMs: Date.now() - startTime,
        truncated: false
      };
    }
    if (!args["prompt"]) {
      return {
        success: false,
        error: "Missing required parameter: prompt",
        durationMs: Date.now() - startTime,
        truncated: false
      };
    }
    const subAgentType = args["subAgentType"];
    const prompt = args["prompt"];
    const agents = await loadAllAgentsDefault();
    const agentDef = findAgentById(subAgentType, agents);
    if (!agentDef || !agentDef.metadata.subagent) {
      const validIds = getSubAgents(agents).map((a) => a.metadata.id);
      return {
        success: false,
        error: `Unknown sub-agent type: ${subAgentType}. Available types: ${validIds.join(", ")}`,
        durationMs: Date.now() - startTime,
        truncated: false
      };
    }
    const { sessionId, sessionManager, llmClient, statsIdentity, providerManager } = context;
    if (!sessionId || !sessionManager || !llmClient) {
      return {
        success: false,
        error: "Missing required context: sessionId, sessionManager, or llmClient",
        durationMs: Date.now() - startTime,
        truncated: false
      };
    }
    try {
      const { getToolRegistryForAgent: getToolRegistryForAgent2 } = await import("./tools-ROBSLYLU.js");
      const toolRegistry = getToolRegistryForAgent2(agentDef);
      const turnMetrics = new TurnMetrics();
      const result = await executeSubAgent({
        subAgentType,
        prompt,
        sessionManager,
        sessionId,
        llmClient,
        toolRegistry,
        turnMetrics,
        providerManager,
        statsIdentity: statsIdentity ?? {
          providerId: "unknown",
          providerName: "Unknown",
          backend: "unknown",
          model: llmClient.getModel()
        },
        ...context.signal ? { signal: context.signal } : {},
        ...context.onEvent ? { onMessage: context.onEvent } : {}
      });
      return {
        success: true,
        output: result.content,
        durationMs: Date.now() - startTime,
        truncated: false
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error during sub-agent execution",
        durationMs: Date.now() - startTime,
        truncated: false
      };
    }
  }
};

