// src/server/tools/workspace.ts
var workspaceTool = createTool(
  "workspace",
  {
    type: "function",
    function: {
      name: "workspace",
      description: `Manage workspaces for the current session. A workspace is a cloned copy of the project.

Use "switch" to move between workspaces. Target "original" for the project root, or a workspace name.
If the workspace does not exist yet, it is created automatically, inheriting the session's current branch.

You can also change the branch of the current workspace by calling switch with the current
workspace name and a branch parameter. The branch will be checked out without recreating
the workspace and without losing uncommitted changes.

If the requested branch does not exist, it will be created. By default it is based on the
default branch of the project (origin/HEAD). You can specify sourceBranch to base the new
branch on a different existing branch.

Setup commands (e.g. npm install) are configured via .openfox/workspace.json.

Actions:
- switch: Switch to a workspace (target: "original" or a name, optional branch for new workspaces)
- list: List all workspaces with their current branch and active status
- delete: Delete a workspace by name (cannot delete "original"). Use force=true to auto-switch other sessions that reference this workspace.`,
      parameters: {
        type: "object",
        properties: {
          action: {
            type: "string",
            enum: ["switch", "list", "delete"],
            description: "The action to perform"
          },
          target: {
            type: "string",
            description: 'For switch: "original" or a workspace name. For delete: the workspace name to delete.'
          },
          branch: {
            type: "string",
            description: "Optional git branch to check out when creating or switching to a workspace"
          },
          sourceBranch: {
            type: "string",
            description: "If branch does not exist, base the new branch on this existing branch. Default: origin/HEAD."
          },
          force: {
            type: "boolean",
            description: "For action=delete: force deletion by auto-switching other sessions that reference this workspace to original first."
          }
        },
        required: ["action"]
      }
    }
  },
  async (args, context, helpers) => {
    const { sessionId, sessionManager } = context;
    const validActions = ["switch", "list", "delete"];
    if (!validActions.includes(args.action)) {
      return helpers.error(`Invalid action: ${args.action}. Must be one of: ${validActions.join(", ")}`);
    }
    switch (args.action) {
      case "switch": {
        if (!args.target || typeof args.target !== "string") {
          return helpers.error('Parameter "target" is required for action=switch ("original" or a workspace name)');
        }
        if (await isGitRepository(context.workdir) === false) {
          return helpers.error("Project is not a git repository");
        }
        const currentSession = sessionManager.getSession(sessionId);
        const isBranchChange = args.branch !== void 0 && currentSession != null && args.target !== "original" && currentSession.workspace?.split("/").pop() === args.target;
        const label = args.target === "original" ? "original project" : `workspace "${args.target}"`;
        const desc = isBranchChange ? `Change branch to "${args.branch}" on ${label}` : `Switch to ${label}${args.branch ? ` on branch "${args.branch}"` : ""}`;
        const approved = await requestUserConfirmation(context, "workspace", desc);
        if (!approved)
          return helpers.error(
            // LLM-facing (rendered into the tool content) — English by design.
            `User denied: ${isBranchChange ? "branch change" : `switch to ${label}`}`
          );
        const updated = await sessionManager.switchWorkspace(sessionId, args.target, args.branch, args.sourceBranch);
        const wsName = args.target === "original" ? "original" : updated.workspace?.split("/").pop() ?? args.target;
        const branch = await getGitBranch(updated.workspace ?? updated.workdir);
        return helpers.success(
          JSON.stringify(
            {
              workspace: wsName,
              path: updated.workspace ?? updated.workdir,
              branch,
              message: args.target === "original" ? "Switched to original project" : `Switched to workspace "${wsName}" on branch "${branch ?? "unknown"}"`
            },
            null,
            2
          )
        );
      }
      case "list": {
        const session = sessionManager.getSession(sessionId);
        if (!session) return helpers.error("Session not found");
        const project = sessionManager.getProject(session.projectId);
        if (!project) return helpers.error("Project not found");
        const currentBranch = await getGitBranch(sessionManager.getEffectiveWorkdir(session.id));
        const named = await listWorkspaces(project.name, project.workdir);
        const activeWsName = session.workspace?.split("/").pop() ?? null;
        const workspaces = [
          { name: "original", branch: currentBranch, active: !session.workspace },
          ...named.map((ws) => ({
            name: ws.name,
            branch: ws.branch,
            active: ws.name === activeWsName
          }))
        ];
        return helpers.success(JSON.stringify({ workspaces }, null, 2));
      }
      case "delete": {
        if (!args.target || typeof args.target !== "string") {
          return helpers.error('Parameter "target" is required for action=delete (the workspace name)');
        }
        if (args.target === "original") return helpers.error("Cannot delete the original workspace");
        if (await isGitRepository(context.workdir) === false) {
          return helpers.error("Project is not a git repository");
        }
        const forceDesc = args.force ? " (will auto-switch other sessions to original)" : "";
        const approved = await requestUserConfirmation(
          context,
          "workspace",
          `Delete workspace "${args.target}"${forceDesc}`
        );
        if (!approved)
          return helpers.error(
            // LLM-facing (rendered into the tool content) — English by design.
            `User denied: delete workspace "${args.target}"`
          );
        await sessionManager.deleteWorkspace(sessionId, args.target, args.force === true);
        return helpers.success(
          JSON.stringify(
            {
              workspace: args.target,
              message: `Workspace "${args.target}" has been deleted`
            },
            null,
            2
          )
        );
      }
      default:
        return helpers.error(`Unknown action: ${args.action}`);
    }
  }
);

